			">=": "greaterthanorequal",
			"in": "in",
			"not in": "notin",
			"between": "between",
			"not between": "notbetween",
			"is empty": "isempty",
			"is null": "isnull",
			"is not null": "isnotnull",
			"is not empty": "isnotempty"
